-- Module 35: provider-neutral subscription, entitlement, usage, and billing-event architecture.
create table public.plans(
 key text primary key check(key in('free_assessment','starter','pro','growth','multi_branch')),name text not null unique,description text not null,tier_rank smallint not null unique check(tier_rank between 0 and 100),grace_period_days smallint not null default 7 check(grace_period_days between 0 and 30),is_public boolean not null default true,is_active boolean not null default true,created_at timestamptz not null default now(),updated_at timestamptz not null default now()
);
insert into public.plans(key,name,description,tier_rank,grace_period_days)values
('free_assessment','Free Assessment','Business Health Assessment and onboarding recommendations without paid operational features.',0,0),
('starter','Starter','Essential records for a small business beginning digital operations.',10,7),
('pro','Pro','Expanded operations, reporting, and advisor capabilities.',20,7),
('growth','Growth','Automation and cross-team operational capabilities for a growing business.',30,7),
('multi_branch','Multi-Branch','Centralized capabilities and higher limits for businesses operating multiple branches.',40,10);
create trigger set_updated_at before update on public.plans for each row execute function private.set_updated_at();

create table public.subscription_features(
 plan_key text not null references public.plans(key)on delete cascade,feature_key text not null check(feature_key~'^[a-z][a-z0-9_]{0,79}$'),is_enabled boolean not null default true,configuration jsonb not null default'{}'check(jsonb_typeof(configuration)='object'),created_at timestamptz not null default now(),primary key(plan_key,feature_key)
);
insert into public.subscription_features(plan_key,feature_key)values
