('pro','assessment'),('pro','core_records'),('pro','product_catalog'),('pro','sales'),('pro','expenses'),('pro','crm'),('pro','inventory'),('pro','purchasing'),('pro','invoicing'),('pro','reports'),('pro','ai_advisor'),
('growth','assessment'),('growth','core_records'),('growth','product_catalog'),('growth','sales'),('growth','expenses'),('growth','crm'),('growth','inventory'),('growth','purchasing'),('growth','invoicing'),('growth','reports'),('growth','ai_advisor'),('growth','ai_recommendations'),('growth','workflow'),('growth','approvals'),('growth','loyalty'),('growth','employees'),('growth','delivery'),
('multi_branch','assessment'),('multi_branch','core_records'),('multi_branch','product_catalog'),('multi_branch','sales'),('multi_branch','expenses'),('multi_branch','crm'),('multi_branch','inventory'),('multi_branch','purchasing'),('multi_branch','invoicing'),('multi_branch','reports'),('multi_branch','ai_advisor'),('multi_branch','ai_recommendations'),('multi_branch','workflow'),('multi_branch','approvals'),('multi_branch','loyalty'),('multi_branch','employees'),('multi_branch','delivery'),('multi_branch','multi_branch');

create table public.usage_limits(
 plan_key text not null references public.plans(key)on delete cascade,usage_key text not null check(usage_key in('max_branches','max_active_users','monthly_transactions')),limit_value bigint check(limit_value is null or limit_value>=0),period text not null check(period in('current','monthly')),enforcement_mode text not null check(enforcement_mode in('resource_count','counter')),created_at timestamptz not null default now(),primary key(plan_key,usage_key)
);
