('growth','max_branches',3,'current','resource_count'),('growth','max_active_users',30,'current','resource_count'),('growth','monthly_transactions',25000,'monthly','resource_count'),
('multi_branch','max_branches',null,'current','resource_count'),('multi_branch','max_active_users',null,'current','resource_count'),('multi_branch','monthly_transactions',null,'monthly','resource_count');

alter table public.module_definitions drop constraint if exists module_definitions_minimum_plan_check;
alter table public.module_definitions add constraint module_definitions_minimum_plan_check check(minimum_plan in('free_assessment','starter','pro','growth','multi_branch'));
alter table public.business_os_templates drop constraint if exists business_os_templates_minimum_plan_check;
alter table public.business_os_templates add constraint business_os_templates_minimum_plan_check check(minimum_plan in('free_assessment','starter','pro','growth','multi_branch'));

update public.subscriptions set status='grace_period'where status='past_due';
alter table public.subscriptions drop constraint subscriptions_status_check;
alter table public.subscriptions add constraint subscriptions_status_check check(status in('trialing','active','grace_period','expired','canceled','paused')),
 alter column provider set default'internal',add constraint subscriptions_plan_key_fkey foreign key(plan_key)references public.plans(key)on update cascade,
 add column pending_plan_key text references public.plans(key),add column cancel_at_period_end boolean not null default false,add column grace_period_end timestamptz,add column started_at timestamptz,add column canceled_at timestamptz,add column expired_at timestamptz,add column provider_metadata jsonb not null default'{}'check(jsonb_typeof(provider_metadata)='object'),add column version bigint not null default 1 check(version>0),
 add check(grace_period_end is null or current_period_end is null or grace_period_end>=current_period_end);
update public.subscriptions set started_at=coalesce(current_period_start,created_at);
create index subscriptions_status_period_idx on public.subscriptions(status,current_period_end)where status in('trialing','active','grace_period');

create table public.subscription_usage(
 id uuid primary key default gen_random_uuid(),organization_id uuid not null references public.subscriptions(organization_id)on delete cascade,usage_key text not null,period_start date not null,period_end date not null,used_quantity bigint not null default 0 check(used_quantity>=0),updated_at timestamptz not null default now(),unique(organization_id,usage_key,period_start),check(period_end>=period_start)
);
create index subscription_usage_lookup_idx on public.subscription_usage(organization_id,usage_key,period_start desc);
create table public.billing_events(
 id uuid primary key default gen_random_uuid(),organization_id uuid not null references public.organizations(id)on delete cascade,subscription_id uuid,event_type text not null check(event_type in('free_started','trial_started','change_requested','cancel_requested','renewal_requested','subscription_activated','plan_changed','renewed','payment_failed','payment_recovered','canceled','expired','usage_recorded','usage_rejected')),provider text not null default'internal',external_event_id text,idempotency_key text not null check(char_length(btrim(idempotency_key))between 8 and 180),actor_id uuid references auth.users(id),from_plan_key text references public.plans(key),to_plan_key text references public.plans(key),details jsonb not null default'{}'check(jsonb_typeof(details)='object'),occurred_at timestamptz not null default clock_timestamp(),foreign key(subscription_id,organization_id)references public.subscriptions(id,organization_id)on delete cascade,unique(organization_id,idempotency_key),unique(provider,external_event_id)
);
create index billing_events_history_idx on public.billing_events(organization_id,occurred_at desc,id);
create index billing_events_subscription_idx on public.billing_events(subscription_id)where subscription_id is not null;

create function private.ensure_free_subscription(requested_organization_id uuid)returns void language plpgsql security definer set search_path='' as $$declare subscription_key uuid;begin if exists(select 1 from public.subscriptions where organization_id=requested_organization_id)then return;end if;insert into public.subscriptions(organization_id,provider,plan_key,status,started_at,entitlements)values(requested_organization_id,'internal','free_assessment','active',clock_timestamp(),'{}')on conflict(organization_id)do nothing returning id into subscription_key;if subscription_key is not null then insert into public.billing_events(organization_id,subscription_id,event_type,idempotency_key,actor_id,to_plan_key)values(requested_organization_id,subscription_key,'free_started','free-started:'||requested_organization_id,auth.uid(),'free_assessment')on conflict do nothing;end if;end$$;
revoke all on function private.ensure_free_subscription(uuid)from public,anon,authenticated;

create or replace function private.set_business_module_state(requested_organization_id uuid,requested_module_key text,requested_enabled boolean,requested_configuration jsonb default'{}')returns void language plpgsql security definer set search_path='' as $$
declare definition public.module_definitions%rowtype;missing_dependencies text[];blocking_dependents text[];current_plan text;full_mvp_access boolean:=false;current_plan_rank integer;minimum_plan_rank integer;
begin
 if auth.uid()is null or not private.can_business_permission(requested_organization_id,'module.manage',null)then raise exception'Permission denied.'using errcode='42501';end if;
 if requested_module_key!~'^[a-z][a-z0-9_]*$'or jsonb_typeof(requested_configuration)<>'object'then raise exception'Invalid module request.'using errcode='22023';end if;
 perform pg_catalog.pg_advisory_xact_lock(pg_catalog.hashtextextended(requested_organization_id::text,0));
 select*into definition from public.module_definitions where key=requested_module_key and status='published';if not found then raise exception'Published module not found.'using errcode='22023';end if;
 if requested_enabled then
  select plan_key,coalesce((entitlements->>'fullMvpAccess')::boolean,false)into current_plan,full_mvp_access from public.subscriptions where organization_id=requested_organization_id and status in('trialing','active','grace_period')limit 1;
  current_plan:=coalesce(current_plan,'starter');
  current_plan_rank:=case when full_mvp_access then 100 else case current_plan when'free_assessment'then 0 when'starter'then 1 when'pro'then 2 when'growth'then 3 when'multi_branch'then 4 else -1 end end;
  minimum_plan_rank:=case definition.minimum_plan when'free_assessment'then 0 when'starter'then 1 when'pro'then 2 when'growth'then 3 when'multi_branch'then 4 else 100 end;
  if current_plan_rank<minimum_plan_rank then raise exception'Module requires the % plan.',definition.minimum_plan using errcode='P0001';end if;
  select array_agg(dependency.dependency_module_key order by dependency.dependency_module_key)into missing_dependencies from public.module_dependencies dependency where dependency.module_key=requested_module_key and not exists(select 1 from public.organization_modules business_module join public.module_definitions dependency_definition on dependency_definition.id=business_module.module_id where business_module.organization_id=requested_organization_id and dependency_definition.key=dependency.dependency_module_key and business_module.is_enabled);
  if coalesce(cardinality(missing_dependencies),0)>0 then raise exception'Enable required modules first: %.',array_to_string(missing_dependencies,', ')using errcode='P0001';end if;
  if not private.module_configuration_is_valid(definition.configuration_schema,requested_configuration)then raise exception'Invalid module configuration.'using errcode='22023';end if;
  insert into public.organization_modules(organization_id,module_id,config,enabled_at,enabled_by,is_enabled)values(requested_organization_id,definition.id,requested_configuration,now(),auth.uid(),true)on conflict(organization_id,module_id)do update set config=excluded.config,enabled_at=now(),enabled_by=auth.uid(),is_enabled=true,updated_at=now();
 else
  select array_agg(dependent.key order by dependent.key)into blocking_dependents from public.module_dependencies dependency join public.module_definitions dependent on dependent.key=dependency.module_key join public.organization_modules business_module on business_module.module_id=dependent.id and business_module.organization_id=requested_organization_id and business_module.is_enabled where dependency.dependency_module_key=requested_module_key;
  if coalesce(cardinality(blocking_dependents),0)>0 then raise exception'Module is required by enabled modules: %.',array_to_string(blocking_dependents,', ')using errcode='P0001';end if;
  update public.organization_modules set is_enabled=false,updated_at=now()where organization_id=requested_organization_id and module_id=definition.id;
 end if;
end$$;

create or replace function private.activate_business_trial()returns trigger language plpgsql security definer set search_path='' as $$
declare trial_started_at timestamptz:=now();
begin
 insert into public.business_trials(organization_id,installation_id,trial_start_date,trial_end_date,activated_by)values(new.organization_id,new.id,trial_started_at,trial_started_at+interval'45 days',new.installed_by)on conflict(organization_id)do nothing;
 if found then
  insert into public.business_trial_milestones(organization_id,milestone_key,due_day,status,achieved_at,evidence)values(new.organization_id,'day_1_os_created',1,'achieved',trial_started_at,jsonb_build_object('installationId',new.id)),(new.organization_id,'day_7_setup',7,'pending',null,'{}'),(new.organization_id,'day_15_operational',15,'pending',null,'{}'),(new.organization_id,'day_30_insights',30,'pending',null,'{}'),(new.organization_id,'day_40_value_report',40,'pending',null,'{}'),(new.organization_id,'day_45_conversion',45,'pending',null,'{}');
  insert into public.subscriptions(organization_id,provider,plan_key,status,current_period_start,current_period_end,started_at,entitlements)values(new.organization_id,'negosyoos_trial','pro','trialing',trial_started_at,trial_started_at+interval'45 days',trial_started_at,'{"trial":true,"fullMvpAccess":true}'::jsonb)
  on conflict(organization_id)do update set provider='negosyoos_trial',plan_key='pro',status='trialing',current_period_start=excluded.current_period_start,current_period_end=excluded.current_period_end,started_at=coalesce(public.subscriptions.started_at,excluded.started_at),entitlements=public.subscriptions.entitlements||excluded.entitlements,updated_at=now(),version=public.subscriptions.version+1 where public.subscriptions.plan_key='free_assessment'or public.subscriptions.status<>'active';
  insert into public.billing_events(organization_id,subscription_id,event_type,idempotency_key,actor_id,from_plan_key,to_plan_key,details)select new.organization_id,subscription.id,'trial_started','trial-started:'||new.organization_id,new.installed_by,case when subscription.created_at<trial_started_at then'free_assessment'else null end,'pro',jsonb_build_object('trialEndDate',trial_started_at+interval'45 days')from public.subscriptions subscription where subscription.organization_id=new.organization_id on conflict do nothing;
 end if;return new;
end$$;

create function private.refresh_subscription_state(requested_organization_id uuid)returns void language plpgsql security definer set search_path='' as $$declare subscription public.subscriptions%rowtype;begin select*into subscription from public.subscriptions where organization_id=requested_organization_id for update;if subscription.organization_id is null then return;end if;if subscription.status='grace_period'and subscription.grace_period_end is not null and clock_timestamp()>=subscription.grace_period_end then update public.subscriptions set status='expired',expired_at=clock_timestamp(),version=version+1 where id=subscription.id;insert into public.billing_events(organization_id,subscription_id,event_type,idempotency_key,from_plan_key,to_plan_key,details)values(requested_organization_id,subscription.id,'expired','expired:'||subscription.id||':'||subscription.version,subscription.plan_key,subscription.plan_key,jsonb_build_object('gracePeriodEnd',subscription.grace_period_end));end if;end$$;
create function private.subscription_feature_allowed(requested_organization_id uuid,requested_feature_key text)returns boolean language plpgsql volatile security definer set search_path='' as $$declare subscription public.subscriptions%rowtype;begin if auth.uid()is null or not private.can_business_permission(requested_organization_id,'organization.read',null)then return false;end if;select*into subscription from public.subscriptions where organization_id=requested_organization_id;if subscription.organization_id is null or subscription.status not in('trialing','active','grace_period')or(subscription.status='grace_period'and subscription.grace_period_end<=clock_timestamp())then return false;end if;if subscription.status='trialing'and subscription.entitlements->>'fullMvpAccess'='true'then return true;end if;return exists(select 1 from public.subscription_features feature where feature.plan_key=subscription.plan_key and feature.feature_key=requested_feature_key and feature.is_enabled);end$$;
revoke all on function private.subscription_feature_allowed(uuid,text),private.refresh_subscription_state(uuid)from public,anon,authenticated;

create function public.assert_subscription_feature(requested_organization_id uuid,requested_feature_key text)returns void language plpgsql security definer set search_path='' as $$begin perform private.ensure_free_subscription(requested_organization_id);perform private.refresh_subscription_state(requested_organization_id);if not private.subscription_feature_allowed(requested_organization_id,requested_feature_key)then raise exception'Subscription feature is unavailable.'using errcode='42501';end if;end$$;
create function public.check_subscription_limit(requested_organization_id uuid,requested_usage_key text,requested_delta bigint default 0)returns jsonb language plpgsql security definer set search_path='' as $$declare subscription public.subscriptions%rowtype;limit_row public.usage_limits%rowtype;used bigint:=0;begin if auth.uid()is null or not private.can_business_permission(requested_organization_id,'organization.read',null)or requested_delta<0 then raise exception'Permission denied.'using errcode='42501';end if;perform private.ensure_free_subscription(requested_organization_id);perform private.refresh_subscription_state(requested_organization_id);select*into subscription from public.subscriptions where organization_id=requested_organization_id;select*into limit_row from public.usage_limits where plan_key=subscription.plan_key and usage_key=requested_usage_key;if limit_row.plan_key is null then raise exception'Unknown usage limit.'using errcode='22023';end if;if requested_usage_key='max_branches'then select count(*)into used from public.branches where organization_id=requested_organization_id;elsif requested_usage_key='max_active_users'then select count(*)into used from public.organization_memberships where organization_id=requested_organization_id and status='active';elsif requested_usage_key='monthly_transactions'then select count(*)into used from public.sales_transactions where organization_id=requested_organization_id and created_at>=date_trunc('month',clock_timestamp()at time zone'Asia/Manila')at time zone'Asia/Manila'and status not in('suspended','voided');end if;return jsonb_build_object('usageKey',requested_usage_key,'used',used,'limit',limit_row.limit_value,'requestedDelta',requested_delta,'allowed',subscription.status in('trialing','active','grace_period')and(limit_row.limit_value is null or used+requested_delta<=limit_row.limit_value));end$$;

create function public.get_subscription_dashboard(requested_organization_id uuid)returns jsonb language plpgsql security definer set search_path='' as $$declare subscription public.subscriptions%rowtype;features jsonb;limits jsonb;begin if auth.uid()is null or not private.can_business_permission(requested_organization_id,'subscription.read',null)then raise exception'Permission denied.'using errcode='42501';end if;perform private.ensure_free_subscription(requested_organization_id);perform private.refresh_subscription_state(requested_organization_id);select*into subscription from public.subscriptions where organization_id=requested_organization_id;select coalesce(jsonb_agg(feature.feature_key order by feature.feature_key),'[]')into features from public.subscription_features feature where feature.plan_key=subscription.plan_key and feature.is_enabled;select coalesce(jsonb_agg(jsonb_build_object('key',limit_row.usage_key,'limit',limit_row.limit_value,'period',limit_row.period)order by limit_row.usage_key),'[]')into limits from public.usage_limits limit_row where limit_row.plan_key=subscription.plan_key;return jsonb_build_object('id',subscription.id,'planKey',subscription.plan_key,'status',subscription.status,'provider',subscription.provider,'currentPeriodStart',subscription.current_period_start,'currentPeriodEnd',subscription.current_period_end,'gracePeriodEnd',subscription.grace_period_end,'pendingPlanKey',subscription.pending_plan_key,'cancelAtPeriodEnd',subscription.cancel_at_period_end,'features',features,'limits',limits);end$$;

create function public.request_subscription_change(requested_organization_id uuid,requested_operation text,requested_plan_key text,requested_idempotency_key text)returns uuid language plpgsql security definer set search_path='' as $$declare actor uuid:=auth.uid();subscription public.subscriptions%rowtype;current_rank smallint;requested_rank smallint;event_key uuid;event_name text;target_plan text;begin if actor is null or not private.can_business_permission(requested_organization_id,'subscription.manage',null)then raise exception'Permission denied.'using errcode='42501';end if;select*into subscription from public.subscriptions where organization_id=requested_organization_id for update;if subscription.organization_id is null then raise exception'Subscription not found.'using errcode='22023';end if;select tier_rank into current_rank from public.plans where key=subscription.plan_key;select tier_rank into requested_rank from public.plans where key=requested_plan_key and is_active;if requested_operation in('upgrade','downgrade')then if requested_rank is null or(requested_operation='upgrade'and requested_rank<=current_rank)or(requested_operation='downgrade'and requested_rank>=current_rank)then raise exception'Invalid plan change.'using errcode='22023';end if;event_name:='change_requested';target_plan:=requested_plan_key;elsif requested_operation='cancel'then event_name:='cancel_requested';target_plan:=subscription.plan_key;elsif requested_operation='renew'then event_name:='renewal_requested';target_plan:=subscription.plan_key;else raise exception'Invalid subscription operation.'using errcode='22023';end if;insert into public.billing_events(organization_id,subscription_id,event_type,idempotency_key,actor_id,from_plan_key,to_plan_key,details)values(requested_organization_id,subscription.id,event_name,btrim(requested_idempotency_key),actor,subscription.plan_key,target_plan,jsonb_build_object('operation',requested_operation))on conflict(organization_id,idempotency_key)do nothing returning id into event_key;if event_key is null then select id into event_key from public.billing_events where organization_id=requested_organization_id and idempotency_key=btrim(requested_idempotency_key);return event_key;end if;if requested_operation in('upgrade','downgrade')then update public.subscriptions set pending_plan_key=requested_plan_key,version=version+1 where id=subscription.id;elsif requested_operation='cancel'then update public.subscriptions set cancel_at_period_end=true,version=version+1 where id=subscription.id;else update public.subscriptions set cancel_at_period_end=false,version=version+1 where id=subscription.id;end if;return event_key;end$$;

create function public.apply_subscription_billing_event(requested_organization_id uuid,requested_provider text,requested_external_event_id text,requested_event_type text,requested_plan_key text,requested_period_start timestamptz,requested_period_end timestamptz,requested_payload jsonb default'{}')returns uuid language plpgsql security definer set search_path='' as $$declare subscription public.subscriptions%rowtype;event_key uuid;grace_days smallint;begin if jsonb_typeof(requested_payload)<>'object'or char_length(btrim(requested_external_event_id))<8 then raise exception'Invalid provider event.'using errcode='22023';end if;select*into subscription from public.subscriptions where organization_id=requested_organization_id for update;if subscription.organization_id is null then raise exception'Subscription not found.'using errcode='22023';end if;if requested_event_type not in('subscription_activated','plan_changed','renewed','payment_failed','payment_recovered','canceled')then raise exception'Invalid provider event type.'using errcode='22023';end if;insert into public.billing_events(organization_id,subscription_id,event_type,provider,external_event_id,idempotency_key,from_plan_key,to_plan_key,details)values(requested_organization_id,subscription.id,requested_event_type,btrim(requested_provider),btrim(requested_external_event_id),'provider:'||btrim(requested_provider)||':'||btrim(requested_external_event_id),subscription.plan_key,coalesce(requested_plan_key,subscription.plan_key),requested_payload)on conflict(provider,external_event_id)do nothing returning id into event_key;if event_key is null then select id into event_key from public.billing_events where provider=btrim(requested_provider)and external_event_id=btrim(requested_external_event_id);return event_key;end if;if requested_event_type in('subscription_activated','plan_changed','renewed','payment_recovered')then update public.subscriptions set provider=btrim(requested_provider),plan_key=coalesce(requested_plan_key,plan_key),pending_plan_key=null,status='active',current_period_start=requested_period_start,current_period_end=requested_period_end,grace_period_end=null,cancel_at_period_end=false,expired_at=null,version=version+1 where id=subscription.id;elsif requested_event_type='payment_failed'then select grace_period_days into grace_days from public.plans where key=subscription.plan_key;update public.subscriptions set status='grace_period',grace_period_end=coalesce(requested_period_end,clock_timestamp())+make_interval(days=>grace_days),version=version+1 where id=subscription.id;else update public.subscriptions set status='canceled',canceled_at=clock_timestamp(),cancel_at_period_end=false,version=version+1 where id=subscription.id;end if;return event_key;end$$;

alter table public.plans enable row level security;alter table public.subscription_features enable row level security;alter table public.usage_limits enable row level security;alter table public.subscription_usage enable row level security;alter table public.billing_events enable row level security;
create policy plans_catalog_read on public.plans for select to authenticated using(is_public and is_active);create policy subscription_features_catalog_read on public.subscription_features for select to authenticated using(exists(select 1 from public.plans plan where plan.key=plan_key and plan.is_public and plan.is_active));create policy usage_limits_catalog_read on public.usage_limits for select to authenticated using(exists(select 1 from public.plans plan where plan.key=plan_key and plan.is_public and plan.is_active));create policy subscription_usage_business_read on public.subscription_usage for select to authenticated using(private.can_business_permission(organization_id,'subscription.read',null));create policy billing_events_business_read on public.billing_events for select to authenticated using(private.can_business_permission(organization_id,'subscription.read',null));
drop policy if exists subscriptions_insert_authorized on public.subscriptions;drop policy if exists subscriptions_update_authorized on public.subscriptions;drop policy if exists subscriptions_delete_authorized on public.subscriptions;
revoke all on public.plans,public.subscription_features,public.usage_limits,public.subscription_usage,public.billing_events from public,anon,authenticated;grant select on public.plans,public.subscription_features,public.usage_limits,public.subscription_usage,public.billing_events to authenticated;revoke insert,update,delete on public.subscriptions from authenticated;
revoke all on function public.assert_subscription_feature(uuid,text),public.check_subscription_limit(uuid,text,bigint),public.get_subscription_dashboard(uuid),public.request_subscription_change(uuid,text,text,text),public.apply_subscription_billing_event(uuid,text,text,text,text,timestamptz,timestamptz,jsonb)from public,anon,authenticated;
grant execute on function public.assert_subscription_feature(uuid,text),public.check_subscription_limit(uuid,text,bigint),public.get_subscription_dashboard(uuid),public.request_subscription_change(uuid,text,text,text)to authenticated;grant execute on function public.apply_subscription_billing_event(uuid,text,text,text,text,timestamptz,timestamptz,jsonb)to service_role;
comment on function public.assert_subscription_feature(uuid,text)is'Server-side subscription entitlement guard. UI visibility is never treated as authorization.';
comment on function public.apply_subscription_billing_event(uuid,text,text,text,text,timestamptz,timestamptz,jsonb)is'Provider-neutral, idempotent service-role boundary for verified payment-provider events.';
